<html lang="en">
  <head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Terms consent</title>
    <style>
      :root {
        color-scheme: light dark;
        --bg: #f4f7fb;
        --surface: rgba(255, 255, 255, 0.94);
        --surface-border: rgba(15, 23, 42, 0.08);
        --text: #0f172a;
        --muted: #475569;
        --accent: #2563eb;
        --accent-strong: #1d4ed8;
        --success-bg: #ecfdf3;
        --success-text: #166534;
        --shadow: 0 24px 60px rgba(15, 23, 42, 0.16);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, rgba(37, 99, 235, 0.16), transparent 34%),
          linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
      }

      a {
        color: inherit;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        padding: 0.75rem 1rem;
        border-radius: 0.75rem;
        background: #ffffff;
        color: var(--text);
        transform: translateY(-140%);
        transition: transform 0.2s ease;
        z-index: 100;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .page-shell {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 1.5rem;
      }

      .card {
        width: min(100%, 30rem);
        padding: 2rem;
        border: 1px solid var(--surface-border);
        border-radius: 1.5rem;
        background: var(--surface);
        box-shadow: var(--shadow);
        backdrop-filter: blur(14px);
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        font-size: 0.8rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
        color: var(--accent-strong);
      }

      h1 {
        margin: 0 0 0.75rem;
        font-size: clamp(1.8rem, 4vw, 2.4rem);
        line-height: 1.1;
      }

      .intro {
        margin: 0 0 1.5rem;
        color: var(--muted);
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 1rem;
      }

      .form-field {
        display: grid;
        gap: 0.6rem;
        padding: 1rem;
        border: 1px solid rgba(37, 99, 235, 0.16);
        border-radius: 1rem;
        background: rgba(248, 250, 252, 0.92);
      }

      .checkbox-row {
        display: grid;
        grid-template-columns: auto 1fr;
        gap: 0.75rem;
        align-items: start;
      }

      input[type="checkbox"] {
        width: 1.15rem;
        height: 1.15rem;
        margin: 0.15rem 0 0;
        accent-color: var(--accent);
      }

      .checkbox-label {
        font-weight: 600;
        line-height: 1.5;
      }

      .checkbox-label a {
        color: var(--accent-strong);
      }

      .helper-text,
      .error-text,
      .status-text {
        margin: 0;
        font-size: 0.95rem;
        line-height: 1.5;
      }

      .helper-text {
        color: var(--muted);
      }

      .error-text {
        color: #b91c1c;
      }

      .status-text {
        padding: 0.9rem 1rem;
        border-radius: 0.9rem;
        background: var(--success-bg);
        color: var(--success-text);
      }

      .actions {
        display: flex;
      }

      button {
        border: 0;
        border-radius: 999px;
        padding: 0.9rem 1.3rem;
        font: inherit;
        font-weight: 700;
        color: #ffffff;
        background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
        box-shadow: 0 14px 30px rgba(37, 99, 235, 0.28);
        cursor: pointer;
      }

      button:hover {
        filter: brightness(1.03);
      }

      a:focus-visible,
      input:focus-visible,
      button:focus-visible {
        outline: 3px solid #0f172a;
        outline-offset: 3px;
      }

      @media (max-width: 32rem) {
        .page-shell {
          padding: 1rem;
        }

        .card {
          padding: 1.25rem;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto;
          transition: none !important;
        }
      }

      @media (forced-colors: active) {
        .card,
        .form-field,
        .status-text,
        button,
        .skip-link {
          border: 1px solid CanvasText;
          box-shadow: none;
        }

        button {
          background: ButtonFace;
          color: ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <div id="app"></div>
    <script>
      const h = (strings, ...values) =>
        strings.reduce((result, string, index) => result + string + (values[index] ?? ""), "");

      const CheckboxField = ({ invalid }) => h`
        <div class="form-field">
          <div class="checkbox-row">
            <input
              id="consent"
              name="consent"
              type="checkbox"
              required
              aria-describedby="${invalid ? "consent-help consent-error" : "consent-help"}"
              ${invalid ? 'aria-invalid="true"' : ""}
            >
            <label class="checkbox-label" for="consent">
              I agree to the Terms of Use <span aria-hidden="true">*</span>
            </label>
          </div>
          <p class="helper-text" id="consent-help">Required to continue with setup.</p>
          <p class="error-text" id="consent-error" ${invalid ? "" : "hidden"}>
            Error: Please agree to the Terms of Use before continuing.
          </p>
        </div>
      `;

      const SubmitButton = () => '<div class="actions"><button type="submit">Continue</button></div>';

      const StatusMessage = ({ submitted }) =>
        submitted
          ? '<p class="status-text" aria-live="polite">Thanks. Your agreement has been recorded for this session.</p>'
          : "";

      const ConsentForm = ({ invalid, submitted }) => h`
        <form id="consent-form" novalidate>
          ${CheckboxField({ invalid })}
          ${SubmitButton()}
          ${StatusMessage({ submitted })}
        </form>
      `;

      const App = (state) => h`
        <a class="skip-link" href="#maincontent">Skip to main content</a>
        <main id="maincontent" class="page-shell" tabindex="-1">
          <section class="card" aria-labelledby="page-title">
            <p class="eyebrow">Product access</p>
            <h1 id="page-title">Confirm your consent</h1>
            <p class="intro">
              Review the terms once, then confirm your agreement to continue securely.
            </p>
            ${ConsentForm(state)}
          </section>
        </main>
      `;

      const state = {
        invalid: false,
        submitted: false,
      };

      const render = () => {
        document.getElementById("app").innerHTML = App(state);
        const form = document.getElementById("consent-form");
        const checkbox = document.getElementById("consent");

        form.addEventListener("submit", (event) => {
          event.preventDefault();

          if (!checkbox.checked) {
            state.invalid = true;
            state.submitted = false;
            render();
            document.getElementById("consent").focus();
            return;
          }

          state.invalid = false;
          state.submitted = true;
          render();
        });

        checkbox.addEventListener("change", () => {
          if (checkbox.checked && state.invalid) {
            state.invalid = false;
            render();
          }
        });
      };

      render();
    </script>
  </body>
</html>
