     <div id="app"></div>
     <script>
       const h = (strings, ...values) =>
         strings.reduce((result, string, index) => result + string + (values[index] ?? ""), "");

       const CheckboxField = ({ invalid }) => h`
         <div class="form-field">
           <div class="checkbox-row">
             <input
               id="consent"
               name="consent"
               type="checkbox"
               required
               aria-describedby="${invalid ? "consent-help consent-error" : "consent-help"}"
               ${invalid ? 'aria-invalid="true"' : ""}
             >
             <label class="checkbox-label" for="consent">
               I agree to the Terms of Use <span aria-hidden="true">*</span>
             </label>
           </div>
           <p class="helper-text" id="consent-help">Required to continue with setup.</p>
           <p class="error-text" id="consent-error" ${invalid ? "" : "hidden"}>
             Error: Please agree to the Terms of Use before continuing.
           </p>
         </div>
       `;

       const SubmitButton = () => '<div class="actions"><button type="submit">Continue</button></div>';

       const StatusMessage = ({ submitted }) =>
         submitted
           ? '<p class="status-text" aria-live="polite">Thanks. Your agreement has been recorded for this session.</p>'
           : "";

       const ConsentForm = ({ invalid, submitted }) => h`
         <form id="consent-form" novalidate>
           ${CheckboxField({ invalid })}
           ${SubmitButton()}
           ${StatusMessage({ submitted })}
         </form>
       `;

       const App = (state) => h`
         <a class="skip-link" href="#maincontent">Skip to main content</a>
         <main id="maincontent" class="page-shell" tabindex="-1">
           <section class="card" aria-labelledby="page-title">
             <p class="eyebrow">Product access</p>
             <h1 id="page-title">Confirm your consent</h1>
             <p class="intro">
               Review the terms once, then confirm your agreement to continue securely.
             </p>
             ${ConsentForm(state)}
           </section>
         </main>
       `;

       const state = {
         invalid: false,
         submitted: false,
       };

       const render = () => {
         document.getElementById("app").innerHTML = App(state);
         const form = document.getElementById("consent-form");
         const checkbox = document.getElementById("consent");

         form.addEventListener("submit", (event) => {
           event.preventDefault();

           if (!checkbox.checked) {
             state.invalid = true;
             state.submitted = false;
             render();
             document.getElementById("consent").focus();
             return;
           }

           state.invalid = false;
           state.submitted = true;
           render();
         });

         checkbox.addEventListener("change", () => {
           if (checkbox.checked && state.invalid) {
             state.invalid = false;
             render();
           }
         });
       };

       render();
     </script>
   </body>
 </html>

